import * as React from 'react';

import * as stylex from '@stylexjs/stylex';
import { ChevronRight, Ellipsis } from 'lucide-react';

import { icon } from '@/lib/stylex-utils';
import { space, fontSize, duration } from '@/lib/constants.stylex';
import { colors, font } from '@/lib/tokens.stylex';

interface StyleXStyleProps {
  /** StyleX styles merged last — always win over the component's own. */
  style?: stylex.StyleXStyles;
}

export function Breadcrumb({
  style,
  ...props
}: Omit<React.ComponentPropsWithoutRef<'nav'>, 'className' | 'style'> &
  StyleXStyleProps) {
  return <nav aria-label="breadcrumb" {...props} {...stylex.props(style)} />;
}

export function BreadcrumbList({
  style,
  ...props
}: Omit<React.ComponentPropsWithoutRef<'ol'>, 'className' | 'style'> &
  StyleXStyleProps) {
  return <ol {...props} {...stylex.props(styles.list, style)} />;
}

export function BreadcrumbItem({
  style,
  ...props
}: Omit<React.ComponentPropsWithoutRef<'li'>, 'className' | 'style'> &
  StyleXStyleProps) {
  return <li {...props} {...stylex.props(styles.item, style)} />;
}

export function BreadcrumbLink({
  style,
  ...props
}: Omit<React.ComponentPropsWithoutRef<'a'>, 'className' | 'style'> &
  StyleXStyleProps) {
  return <a {...props} {...stylex.props(styles.link, style)} />;
}

export function BreadcrumbPage({
  style,
  ...props
}: Omit<React.ComponentPropsWithoutRef<'span'>, 'className' | 'style'> &
  StyleXStyleProps) {
  return (
    <span
      role="link"
      aria-disabled="true"
      aria-current="page"
      {...props}
      {...stylex.props(styles.page, style)}
    />
  );
}

export function BreadcrumbSeparator({
  children,
  style,
  ...props
}: Omit<React.ComponentPropsWithoutRef<'li'>, 'className' | 'style'> &
  StyleXStyleProps) {
  return (
    <li
      role="presentation"
      aria-hidden
      {...props}
      {...stylex.props(styles.separator, style)}
    >
      {children ?? (
        <ChevronRight {...stylex.props(icon.sm)} />
      )}
    </li>
  );
}

export function BreadcrumbEllipsis({
  style,
  ...props
}: Omit<React.ComponentPropsWithoutRef<'span'>, 'className' | 'style'> &
  StyleXStyleProps) {
  return (
    <span
      role="presentation"
      aria-hidden
      {...props}
      {...stylex.props(styles.ellipsis, style)}
    >
      <Ellipsis {...stylex.props(icon.md)} />
      <span {...stylex.props(styles.srOnly)}>More</span>
    </span>
  );
}

const styles = stylex.create({
  list: {
    alignItems: 'center',
    color: colors.mutedForeground,
    display: 'flex',
    flexWrap: 'wrap',
    fontFamily: font.sans,
    fontSize: fontSize.sm,
    gap: space.s15,
    listStyle: 'none',
    margin: 0,
    overflowWrap: 'break-word',
    padding: 0,
  },
  item: {
    alignItems: 'center',
    display: 'inline-flex',
    gap: space.s1,
  },
  link: {
    color: {
      default: 'inherit',
      ':hover': colors.foreground,
    },
    textDecoration: 'none',
    transitionDuration: duration.fast,
    transitionProperty: 'color',
  },
  page: {
    color: colors.foreground,
  },
  separator: {
    alignItems: 'center',
    display: 'flex',
  },
  ellipsis: {
    alignItems: 'center',
    display: 'flex',
    height: space.s5,
    justifyContent: 'center',
    width: space.s5,
  },
  srOnly: {
    clip: 'rect(0 0 0 0)',
    height: '1px',
    overflow: 'hidden',
    position: 'absolute',
    whiteSpace: 'nowrap',
    width: '1px',
  },
});
